//! 🧪️ The real lower book retains one wallet while an issued return credit is pending.
use super::*;
struct Caller<'a>{source:usize,budget:&'a OriginalReturnBudget,grant:RetainedCloneGrant,fuel:u64}
fn clock()->Option<u64>{Some(0)}
impl OriginalReturnCaptureContext for Caller<'_>{
 fn capture_return_frame(&self)->Result<OriginalReturnCaptureFrame,ValueError>{Ok(OriginalReturnCaptureFrame{source:self.source,clock:1,now:clock,deadline:100,operation:OperationId(1),generation:Generation(1),granted:self.grant,fuel:self.fuel,spent:Default::default(),work:0})}
 fn capture_return_budget(&self)->Option<&OriginalReturnBudget>{Some(self.budget)}
}
#[test]
fn pending_credit_keeps_the_original_book_and_cannot_renew_or_rebind_its_stock(){
 let law:serde_json::Value=serde_json::from_str(include_str!("cases.json")).unwrap();let stock=&law["stock"];let grant=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:stock["release"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};let fuel=stock["fuel"].as_u64().unwrap();let mut source=OriginalReturnSource::empty(1);let identity=&source as*const _ as usize;
 {
 let mut reference=source.try_borrow().unwrap();let input=OriginalReturnSourceInput::capture(&Caller{source:identity,budget:reference.get(),grant,fuel}).unwrap();assert!(reference.get_mut().bind(input).unwrap());let turn=reference.get_mut().admit_table(grant,fuel);let progress=turn.result.unwrap().unwrap();assert_eq!(progress.copied_items,law["table"]["items"].as_u64().unwrap()as usize);assert_eq!(turn.work,law["table"]["work"].as_u64().unwrap());reference.get_mut().record_retained(progress).unwrap();reference.get_mut().record_work(turn.work);
 let mut credit=None;let destination=&mut credit as*mut _ as usize;credit=reference.get_mut().claim(0,destination,0).unwrap();let mut credit=credit.unwrap();let before=reference.get().snapshot();assert!(source.retirement_demands().is_err());assert!(source.retirement_work_demand().is_err());assert_eq!(before.remaining().unwrap().0.maximum_items,law["pending"]["items"].as_u64().unwrap()as usize);assert_eq!(before.remaining().unwrap().1,law["pending"]["fuel"].as_u64().unwrap());assert!(reference.get_mut().renew_turn().is_err());
 let enlarged=RetainedCloneGrant{maximum_items:usize::MAX,maximum_copy_bytes:usize::MAX,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX};let same=OriginalReturnSourceInput::capture(&Caller{source:identity,budget:reference.get(),grant:enlarged,fuel:u64::MAX}).unwrap();assert!(!reference.get_mut().bind(same).unwrap());assert_eq!(reference.get().snapshot(),before);let mut witness=credit.issue_success_return(0).unwrap();reference.get_mut().redeem(&mut credit,&mut witness).unwrap();let posted=reference.get().snapshot();reference.get_mut().redeem(&mut credit,&mut witness).unwrap();assert_eq!(reference.get().snapshot(),posted);reference.get_mut().finish_received(&credit,&mut witness).unwrap();assert!(credit.terminal_is_empty());assert_eq!(posted.remaining().unwrap().0.maximum_items,law["received"]["items"].as_u64().unwrap()as usize);assert_eq!(posted.remaining().unwrap().1,law["received"]["fuel"].as_u64().unwrap());
 }
 for _ in 0..16{if source.terminal_is_empty(){break}let demand=source.retirement_demands().unwrap();let units=source.retirement_work_demand().unwrap();let admitted=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};for axis in law["deniedAxes"].as_array().unwrap(){let mut denied=admitted;match axis.as_str().unwrap(){"items"=>denied.maximum_items=0,"copy" if demand.copy_bytes>0=>denied.maximum_copy_bytes-=1,"release" if demand.release_bytes>0=>denied.maximum_release_bytes-=1,"depth" if demand.depth>0=>denied.maximum_depth-=1,_=>continue}let turn=source.close_step(denied);assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(source.retirement_demands().unwrap(),demand);assert_eq!(source.retirement_work_demand().unwrap(),units)}let turn=source.close_step(admitted);assert_eq!(turn.work,units);assert!(turn.result.unwrap().progress().fits(admitted));}assert!(source.terminal_is_empty());assert_eq!(source.retirement_work_demand().unwrap(),0);assert_eq!(source.retirement_demands().unwrap(),Default::default());
}
